  zh: { guides: WORSHIP_GUIDES_ZH, reference: chineseReference },
  kk: { guides: WORSHIP_GUIDES_KK, reference: kazakhReference },
  vi: { guides: WORSHIP_GUIDES_VI, reference: vietnameseReference },
