// src/content/journeyKk.ts
var JOURNEY_META_KK = {
  umrah: {
    intro: "\u041A\u0456\u0448\u0456 \u049B\u0430\u0436\u044B\u043B\u044B\u049B: \u0438\u0445\u0440\u0430\u043C, \u0442\u0430\u0443\u0430\u043F, \u0441\u04D9\u0493\u0438 \u0436\u04D9\u043D\u0435 \u0448\u0430\u0448\u0442\u044B \u049B\u044B\u0440\u0443 \u043D\u0435 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u0443. \u041E\u043D\u044B \u0436\u044B\u043B\u0434\u044B\u04A3 \u043A\u0435\u0437 \u043A\u0435\u043B\u0433\u0435\u043D \u0443\u0430\u049B\u044B\u0442\u044B\u043D\u0434\u0430 \u043E\u0440\u044B\u043D\u0434\u0430\u0443\u0493\u0430 \u0431\u043E\u043B\u0430\u0434\u044B."
  },
  hajj: {
    intro: "\u0417\u0443\u043B-\u0425\u0438\u0436\u0436\u0430\u043D\u044B\u04A3 8-\u0456 \u043C\u0435\u043D 13-\u0456 \u0430\u0440\u0430\u043B\u044B\u0493\u044B\u043D\u0434\u0430\u0493\u044B \u04AF\u043B\u043A\u0435\u043D \u049B\u0430\u0436\u044B\u043B\u044B\u049B, \u043E\u0440\u0442\u0430\u0441\u044B\u043D\u0434\u0430 \u0410\u0440\u0430\u0444\u0430\u0442\u0442\u0430 \u0442\u04B1\u0440\u0443 \u0431\u0430\u0440."
  }
};
var JOURNEY_STEPS_KK = {
  // umrah
  prepare: {
    title: "\u0414\u0430\u0439\u044B\u043D\u0434\u0430\u043B\u0443 \u0436\u04D9\u043D\u0435 \u043D\u0438\u0435\u0442 \u0435\u0442\u0443",
    short: "\u041C\u0438\u049B\u0430\u0442\u0442\u0430\u043D \u04E9\u0442\u043F\u0435\u0441 \u0431\u04B1\u0440\u044B\u043D \u0438\u0445\u0440\u0430\u043C\u0493\u0430 \u043A\u0456\u0440\u0456\u04A3\u0456\u0437",
    detail: "\u0422\u044B\u0440\u043D\u0430\u049B \u043F\u0435\u043D \u0448\u0430\u0448\u0442\u044B \u0430\u043B\u0434\u044B\u0440\u044B\u043F, \u0493\u04B1\u0441\u044B\u043B \u0430\u043B\u044B\u04A3\u044B\u0437 \u0436\u04D9\u043D\u0435 \u0431\u0430\u0493\u044B\u0442\u044B\u04A3\u044B\u0437\u0493\u0430 \u0442\u0438\u0456\u0441\u0442\u0456 \u043C\u0438\u049B\u0430\u0442\u0442\u0430\u043D \u04E9\u0442\u043F\u0435\u0441 \u0431\u04B1\u0440\u044B\u043D \u0438\u0445\u0440\u0430\u043C \u043A\u0438\u0456\u043C\u0434\u0435\u0440\u0456\u043D \u043A\u0438\u0456\u04A3\u0456\u0437. \u0421\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u043A\u04E9\u04A3\u0456\u043B\u0434\u0435 \u0443\u043C\u0440\u0430\u0493\u0430 \u043D\u0438\u0435\u0442 \u0435\u0442\u0456\u043F, \u0442\u04D9\u043B\u0431\u0438\u044F\u043D\u044B \u0431\u0430\u0441\u0442\u0430\u04A3\u044B\u0437. \u0418\u0445\u0440\u0430\u043C\u0493\u0430 \u043A\u0456\u0440\u0433\u0435\u043D\u043D\u0435\u043D \u043A\u0435\u0439\u0456\u043D \u0448\u0430\u0448 \u043F\u0435\u043D \u0442\u044B\u0440\u043D\u0430\u049B \u0430\u043B\u0434\u044B\u0440\u0443\u0493\u0430, (\u0435\u0440\u043B\u0435\u0440\u0433\u0435) \u0442\u0456\u0433\u0456\u043B\u0433\u0435\u043D \u043A\u0438\u0456\u043C \u043C\u0435\u043D \u0438\u0456\u0441\u0441\u0443 \u049B\u043E\u043B\u0434\u0430\u043D\u0443\u0493\u0430, \u0430\u04A3 \u0430\u0443\u043B\u0430\u0443\u0493\u0430 \u0436\u04D9\u043D\u0435 \u043D\u0435\u043A\u0435 \u049B\u0438\u044E\u0493\u0430 \u0431\u043E\u043B\u043C\u0430\u0439\u0434\u044B \u2014 \u0438\u0445\u0440\u0430\u043C\u0434\u044B \u043D\u0435 \u0431\u04B1\u0437\u0430\u0442\u044B\u043D\u044B \u0436\u04D9\u043D\u0435 \u043E\u043D\u044B\u04A3 \u04E9\u0442\u0435\u0443\u0456 \u043D\u0435 \u0431\u0435\u0440\u0435\u0442\u0456\u043D\u0456 \u043C\u0430\u0437\u04BB\u0430\u0431\u0442\u0430\u0440\u0434\u0430 \u04D9\u0440 \u0442\u04AF\u0440\u043B\u0456, \u0441\u043E\u043D\u0434\u044B\u049B\u0442\u0430\u043D \u04E9\u0437 \u0436\u0430\u0493\u0434\u0430\u0439\u044B\u04A3\u044B\u0437\u0434\u044B \u0441\u0435\u043D\u0435\u0442\u0456\u043D \u0493\u0430\u043B\u044B\u043C\u043C\u0435\u043D \u0440\u0430\u0441\u0442\u0430\u04A3\u044B\u0437."
  },
  talbiyah: {
    title: "\u0422\u04D9\u043B\u0431\u0438\u044F",
    short: "\u0425\u0430\u0440\u0430\u043C\u0493\u0430 \u0436\u0435\u0442\u043A\u0435\u043D\u0448\u0435 \u043E\u043D\u044B \u049B\u0430\u0439\u0442\u0430\u043B\u0430\u0443\u0434\u044B \u0436\u0430\u043B\u0493\u0430\u0441\u0442\u044B\u0440\u044B\u04A3\u044B\u0437",
    detail: "\xAB\u041B\u04D9\u0431\u0431\u04D9\u0439\u043A \u0410\u043B\u043B\u0430\u04BB\u0443\u043C\u043C\u04D9 \u043B\u04D9\u0431\u0431\u04D9\u0439\u043A. \u041B\u04D9\u0431\u0431\u04D9\u0439\u043A\u04D9 \u043B\u04D9 \u0448\u04D9\u0440\u0438\u043A\u04D9 \u043B\u04D9\u043A\u04D9 \u043B\u04D9\u0431\u0431\u04D9\u0439\u043A. \u0418\u043D\u043D\u04D9 \u04D9\u043B-\u0445\u0430\u043C\u0434\u04D9 \u0443\u04D9 \u04D9\u043D-\u043D\u0438\u0493\u043C\u04D9\u0442\u04D9 \u043B\u04D9\u043A\u04D9 \u0443\u04D9 \u04D9\u043B-\u043C\u04AF\u043B\u043A, \u043B\u04D9 \u0448\u04D9\u0440\u0438\u043A\u04D9 \u043B\u04D9\u043A.\xBB \u0415\u0440\u043B\u0435\u0440 \u043E\u043D\u044B \u0434\u0430\u0443\u044B\u0441\u0442\u0430\u043F \u0430\u0439\u0442\u0430\u0434\u044B; \u04D9\u0439\u0435\u043B\u0434\u0435\u0440 \u0456\u0448\u0442\u0435\u0439 \u0430\u0439\u0442\u0430\u0434\u044B. \u0422\u0430\u0443\u0430\u043F\u0442\u044B \u0431\u0430\u0441\u0442\u0430\u0493\u0430\u043D\u0448\u0430 \u0436\u0430\u043B\u0493\u0430\u0441\u0442\u044B\u0440\u044B\u04A3\u044B\u0437."
  },
  tawaf: {
    title: "\u049A\u0430\u0493\u0431\u0430\u043D\u044B \u0442\u0430\u0443\u0430\u043F \u0435\u0442\u0443",
    short: "\u049A\u0430\u0440\u0430 \u0442\u0430\u0441\u0442\u0430\u043D \u0431\u0430\u0441\u0442\u0430\u043B\u0430\u0442\u044B\u043D \u0436\u0435\u0442\u0456 \u0430\u0439\u043D\u0430\u043B\u044B\u043C",
    detail: "\u049A\u0430\u0440\u0430 \u0442\u0430\u0441\u0442\u0430\u043D \u0431\u0430\u0441\u0442\u0430\u0443\u0493\u0430 \u043D\u0438\u0435\u0442 \u0435\u0442\u0456\u043F \u043A\u0456\u0440\u0456\u04A3\u0456\u0437 \u0434\u0435 \u049A\u0430\u0493\u0431\u0430\u043D\u044B \u0441\u043E\u043B \u0436\u0430\u0493\u044B\u04A3\u044B\u0437\u0434\u0430 \u049B\u0430\u043B\u0434\u044B\u0440\u044B\u043F, \u0436\u0435\u0442\u0456 \u0440\u0435\u0442 \u0430\u0439\u043D\u0430\u043B\u044B\u04A3\u044B\u0437. \u049A\u0430\u0440\u0430 \u0442\u0430\u0441\u0442\u044B\u04A3 \u0436\u0430\u043D\u044B\u043D\u0430\u043D \u04D9\u0440 \u04E9\u0442\u043A\u0435\u043D \u0441\u0430\u0439\u044B\u043D \u043E\u0493\u0430\u043D \u049B\u043E\u043B \u0442\u0438\u0433\u0456\u0437\u0456\u04A3\u0456\u0437 \u043D\u0435 \u0438\u0448\u0430\u0440\u0430 \u0436\u0430\u0441\u0430\u04A3\u044B\u0437 \u0436\u04D9\u043D\u0435 \u049B\u043E\u043B\u044B\u04A3\u044B\u0437\u0434\u0430\u043D \u043A\u0435\u043B\u0433\u0435\u043D \u043A\u0435\u0437 \u043A\u0435\u043B\u0433\u0435\u043D \u0437\u0456\u043A\u0456\u0440 \u043D\u0435 \u049A\u04B1\u0440\u0430\u043D \u043E\u049B\u044B\u04A3\u044B\u0437 \u2014 \u04D9\u0440 \u0430\u0439\u043D\u0430\u043B\u044B\u043C\u0493\u0430 \u0430\u0440\u043D\u0430\u0439\u044B \u0431\u0435\u043A\u0456\u0442\u0456\u043B\u0433\u0435\u043D \u0434\u04B1\u0493\u0430 \u0436\u043E\u049B. \u0415\u0440\u043B\u0435\u0440 \u0430\u043B\u0493\u0430\u0448\u049B\u044B \u04AF\u0448 \u0430\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u0430 \u0442\u0435\u0437 \u0436\u04AF\u0440\u0435\u0434\u0456. \u0410\u044F\u049B\u0442\u0430\u0493\u0430\u043D \u0441\u043E\u04A3, \u043C\u04AF\u043C\u043A\u0456\u043D \u0431\u043E\u043B\u0441\u0430, \u041C\u0430\u049B\u0430\u043C \u0418\u0431\u0440\u0430\u04BB\u0438\u043C\u043D\u0456\u04A3 \u0430\u0440\u0442\u044B\u043D\u0434\u0430 \u0435\u043A\u0456 \u0440\u04D9\u043A\u0430\u0442 \u043D\u0430\u043C\u0430\u0437 \u043E\u049B\u044B\u04A3\u044B\u0437, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0417\u04D9\u043C\u0437\u04D9\u043C\u043D\u0435\u043D \u0456\u0448\u0456\u04A3\u0456\u0437.",
    counterLabel: "\u0410\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u0430\u0440"
  },
  sai: {
    title: "\u0421\u0430\u0444\u0430 \u043C\u0435\u043D \u041C\u04D9\u0440\u0443\u0430 \u0430\u0440\u0430\u0441\u044B\u043D\u0434\u0430\u0493\u044B \u0441\u04D9\u0493\u0438",
    short: "\u0415\u043A\u0456 \u0442\u04E9\u0431\u0435\u043D\u0456\u04A3 \u0430\u0440\u0430\u0441\u044B\u043D\u0434\u0430\u0493\u044B \u0436\u0435\u0442\u0456 \u0440\u0435\u0442",
    detail: "\u0421\u0430\u0444\u0430\u0434\u0430\u043D \u041C\u04D9\u0440\u0443\u0430\u0493\u0430 \u0434\u0435\u0439\u0456\u043D \u0436\u04AF\u0440\u0456\u04A3\u0456\u0437 \u2014 \u0431\u04B1\u043B \u0431\u0456\u0440 \u0440\u0435\u0442 \u2014 \u0436\u04D9\u043D\u0435 \u049B\u0430\u0439\u0442\u0430 \u043E\u0440\u0430\u043B\u044B\u04A3\u044B\u0437, \u0431\u0430\u0440\u043B\u044B\u0493\u044B \u0436\u0435\u0442\u0456 \u0440\u0435\u0442, \u041C\u04D9\u0440\u0443\u0430\u0434\u0430 \u0430\u044F\u049B\u0442\u0430\u043B\u0430\u0434\u044B. \u0421\u04D9\u0493\u0438 \u04E9\u0437 \u0430\u043B\u0434\u044B\u043D\u0430 \u0493\u04B1\u0440\u044B\u043F \u0436\u04D9\u043D\u0435 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u044B\u043B\u043C\u0430\u0439\u0434\u044B. \u04E8\u0437 \u049B\u0430\u0440\u049B\u044B\u043D\u044B\u04A3\u044B\u0437\u0431\u0435\u043D \u0436\u04AF\u0440\u0456\u04A3\u0456\u0437; \u0442\u0435\u043A \u0435\u043A\u0456 \u0436\u0430\u0441\u044B\u043B \u0431\u0435\u043B\u0433\u0456\u043D\u0456\u04A3 \u0430\u0440\u0430\u0441\u044B \u0493\u0430\u043D\u0430 \u0442\u0435\u0437\u0434\u0435\u0442\u0456\u043B\u0435\u0434\u0456.",
    counterLabel: "\u0420\u0435\u0442"
  },
  halq: {
    title: "\u0428\u0430\u0448\u0442\u044B \u049B\u044B\u0440\u0443 \u043D\u0435 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u0443",
    short: "\u0418\u0445\u0440\u0430\u043C\u043D\u0430\u043D \u0448\u044B\u0493\u0430\u0440\u0430\u0442\u044B\u043D \u049B\u0430\u0434\u0430\u043C",
    detail: "\u0415\u0440\u043B\u0435\u0440 \u0431\u0430\u0441\u044B\u043D \u049B\u044B\u0440\u0430\u0434\u044B \u043D\u0435 \u0448\u0430\u0448\u044B\u043D \u0442\u04AF\u0433\u0435\u043B \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u0430\u0434\u044B; \u049B\u044B\u0440\u0443 \u0430\u0440\u0442\u044B\u0493\u044B\u0440\u0430\u049B. \u04D8\u0439\u0435\u043B\u0434\u0435\u0440 \u0448\u0430\u0448\u0442\u044B\u04A3 \u04B1\u0448\u044B\u043D\u0430\u043D \u0431\u0456\u0440 \u0441\u0430\u0443\u0441\u0430\u049B \u04B1\u0448\u044B\u043D\u044B\u04A3 \u04B1\u0437\u044B\u043D\u0434\u044B\u0493\u044B\u043D\u0434\u0430\u0439 \u043A\u0435\u0441\u0435\u0434\u0456. \u041E\u0441\u044B\u043C\u0435\u043D \u0443\u043C\u0440\u0430 \u0430\u044F\u049B\u0442\u0430\u043B\u044B\u043F, \u0438\u0445\u0440\u0430\u043C \u0442\u044B\u0439\u044B\u043C \u0441\u0430\u043B\u0493\u0430\u043D\u043D\u044B\u04A3 \u0431\u04D9\u0440\u0456 \u049B\u0430\u0439\u0442\u0430\u0434\u0430\u043D \u0430\u0434\u0430\u043B \u0431\u043E\u043B\u0430\u0434\u044B."
  },
  closing: {
    title: "\u0415\u0441\u043A\u0435 \u0430\u043B\u044B\u043F, \u0441\u0430\u043F\u0430\u0440\u0434\u044B \u0430\u044F\u049B\u0442\u0430\u0443",
    short: "\u0415\u043A\u0456 \u0440\u04D9\u043A\u0430\u0442 \u043E\u049B\u044B\u043F, \u0448\u04AF\u043A\u0456\u0440 \u0435\u0442\u0456\u04A3\u0456\u0437",
    detail: "\u0425\u0430\u0440\u0430\u043C\u0434\u0430 \u049B\u0430\u0439 \u0436\u0435\u0440\u0434\u0435 \u0431\u043E\u043B\u0441\u0430 \u0434\u0430 \u043D\u0430\u043C\u0430\u0437 \u043E\u049B\u044B\u04A3\u044B\u0437, \u0448\u0430\u043C\u0430\u04A3\u044B\u0437 \u043A\u0435\u043B\u0441\u0435 \u0441\u0430\u0434\u0430\u049B\u0430 \u0431\u0435\u0440\u0456\u04A3\u0456\u0437 \u0436\u04D9\u043D\u0435 \u0430\u044F\u049B\u0442\u0430\u043B\u0493\u0430\u043D \u0493\u04B1\u0440\u044B\u043F\u0442\u0430\u043D \u043A\u0435\u0439\u0456\u043D \u0430\u0439\u0442\u044B\u043B\u0430\u0442\u044B\u043D \u0434\u04B1\u0493\u0430\u043D\u044B \u049B\u0430\u043B\u0434\u044B\u0440\u043C\u0430\u04A3\u044B\u0437. \u041A\u04E9\u043F\u0442\u0435\u0433\u0435\u043D \u0430\u0434\u0430\u043C\u0434\u0430\u0440 \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0422\u0430\u043D\u0493\u0438\u043C\u043D\u0430\u043D \u0443\u043C\u0440\u0430\u043D\u044B \u049B\u0430\u0439\u0442\u0430\u043B\u0430\u0439\u0434\u044B \u043D\u0435 \u0431\u0430\u0441\u049B\u0430 \u0431\u0456\u0440\u0435\u0443 \u04AF\u0448\u0456\u043D \u043E\u0440\u044B\u043D\u0434\u0430\u0439\u0434\u044B \u2014 \u0431\u04B1\u043B \u0441\u0456\u0437\u0434\u0456\u04A3 \u043D\u0438\u0435\u0442\u0456\u04A3\u0456\u0437 \u0431\u0435\u043D \u0448\u0430\u043C\u0430\u04A3\u044B\u0437\u0493\u0430 \u0431\u0430\u0439\u043B\u0430\u043D\u044B\u0441\u0442\u044B."
  },
  // hajj
  intention: {
    title: "\u049A\u0430\u0436\u044B\u043B\u044B\u049B \u0442\u04AF\u0440\u0456\u043D \u0442\u0430\u04A3\u0434\u0430\u04A3\u044B\u0437",
    short: "\u0422\u04D9\u043C\u0430\u0442\u0442\u0443\u0493, \u049A\u0438\u0440\u0430\u043D \u043D\u0435\u043C\u0435\u0441\u0435 \u0418\u0444\u0440\u0430\u0434",
    detail: "\u0422\u04D9\u043C\u0430\u0442\u0442\u0443\u0493: \u0443\u043C\u0440\u0430\u0493\u0430 \u0438\u0445\u0440\u0430\u043C \u043A\u0438\u0456\u043F \u043E\u043D\u044B \u0430\u044F\u049B\u0442\u0430\u04A3\u044B\u0437, \u0438\u0445\u0440\u0430\u043C\u043D\u0430\u043D \u0448\u044B\u0493\u044B\u04A3\u044B\u0437, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 8-\u0448\u0456 \u043A\u04AF\u043D\u0456 \u049B\u0430\u0436\u044B\u043B\u044B\u049B \u04AF\u0448\u0456\u043D \u049B\u0430\u0439\u0442\u0430 \u0438\u0445\u0440\u0430\u043C\u0493\u0430 \u043A\u0456\u0440\u0456\u04A3\u0456\u0437; \u043E\u043D\u0434\u0430 \u049B\u04B1\u0440\u0431\u0430\u043D\u0434\u044B\u049B \u0431\u0430\u0440. \u049A\u0438\u0440\u0430\u043D: \u0443\u043C\u0440\u0430 \u043C\u0435\u043D \u049B\u0430\u0436\u044B\u043B\u044B\u049B\u0442\u044B \u0431\u0456\u0440 \u0438\u0445\u0440\u0430\u043C\u0434\u0430 \u04E9\u0442\u043A\u0456\u0437\u0443. \u0418\u0444\u0440\u0430\u0434: \u0442\u0435\u043A \u049B\u0430\u0436\u044B\u043B\u044B\u049B\u049B\u0430 \u0438\u0445\u0440\u0430\u043C \u043A\u0438\u0456\u043F, \u0441\u043E\u04A3\u044B\u043D\u0430 \u0434\u0435\u0439\u0456\u043D \u0438\u0445\u0440\u0430\u043C\u0434\u0430 \u049B\u0430\u043B\u0443. \u049A\u0430\u0439\u0441\u044B\u0441\u044B \u0430\u0440\u0442\u044B\u049B \u0436\u04D9\u043D\u0435 \u04D9\u0440\u049B\u0430\u0439\u0441\u044B\u0441\u044B\u043D\u0430 \u043D\u0435 \u049B\u0430\u0436\u0435\u0442 \u0435\u043A\u0435\u043D\u0456 \u0436\u0430\u0493\u0434\u0430\u0439\u044B\u04A3\u044B\u0437 \u0431\u0435\u043D \u043C\u0430\u0437\u04BB\u0430\u0431\u044B\u04A3\u044B\u0437\u0493\u0430 \u0431\u0430\u0439\u043B\u0430\u043D\u044B\u0441\u0442\u044B \u2014 \u0441\u0430\u043F\u0430\u0440\u0493\u0430 \u0448\u044B\u049B\u043F\u0430\u0441 \u0431\u04B1\u0440\u044B\u043D \u0431\u0456\u043B\u0456\u043F \u0448\u0435\u0448\u0456\u04A3\u0456\u0437."
  },
  ihram: {
    title: "\u0418\u0445\u0440\u0430\u043C\u0493\u0430 \u043A\u0456\u0440\u0443",
    short: "\u0492\u04B1\u0441\u044B\u043B \u0430\u043B\u044B\u04A3\u044B\u0437, \u043A\u0438\u0456\u043D\u0456\u04A3\u0456\u0437, \u043D\u0438\u0435\u0442 \u0435\u0442\u0456\u04A3\u0456\u0437 \u0434\u0435 \u0442\u04D9\u043B\u0431\u0438\u044F\u043D\u044B \u0431\u0430\u0441\u0442\u0430\u04A3\u044B\u0437",
    detail: "\u0492\u04B1\u0441\u044B\u043B \u0430\u043B\u044B\u043F, \u0438\u0445\u0440\u0430\u043C \u043A\u0438\u0456\u043C\u0456\u043D \u043A\u0438\u0456\u04A3\u0456\u0437, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0442\u0430\u04A3\u0434\u0430\u0493\u0430\u043D \u0493\u04B1\u0440\u044B\u043F\u0442\u0430\u0440\u044B\u04A3\u044B\u0437\u0493\u0430 \u043D\u0438\u0435\u0442 \u0435\u0442\u0456\u043F, \u0442\u04D9\u043B\u0431\u0438\u044F\u043D\u044B \u0431\u0430\u0441\u0442\u0430\u04A3\u044B\u0437. \u0422\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u044B\u043F, \u049B\u04B1\u0440\u0431\u0430\u043D \u0448\u0430\u043B\u044B\u043F, \u0448\u0430\u0448 \u049B\u044B\u0440\u043C\u0430\u0439\u044B\u043D\u0448\u0430 \u043D\u0435 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u043F\u0430\u0439\u044B\u043D\u0448\u0430 \u0438\u0445\u0440\u0430\u043C \u0442\u044B\u0439\u044B\u043C\u0434\u0430\u0440\u044B \u043A\u04AF\u0448\u0456\u043D\u0434\u0435 \u049B\u0430\u043B\u0430\u0434\u044B."
  },
  qudum: {
    title: "\u049A\u04B1\u0434\u0443\u043C \u0442\u0430\u0443\u0430\u0431\u044B \u043C\u0435\u043D \u0441\u04D9\u0493\u0438",
    short: "\u049A\u04B1\u0434\u0443\u043C \u0442\u0430\u0443\u0430\u0431\u044B, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0422\u04D9\u043C\u0430\u0442\u0442\u0443\u0493 \u04AF\u0448\u0456\u043D \u0441\u04D9\u0493\u0438",
    detail: "\u041C\u0435\u043A\u043A\u0435\u0433\u0435 \u0436\u0435\u0442\u043A\u0435\u043D\u0434\u0435, \u0436\u0435\u0442\u0456 \u0430\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u044B \u049B\u04B1\u0434\u0443\u043C \u0442\u0430\u0443\u0430\u0431\u044B\u043D \u0436\u0430\u0441\u0430\u043F, \u0435\u043A\u0456 \u0440\u04D9\u043A\u0430\u0442 \u043E\u049B\u044B\u04A3\u044B\u0437. \u0422\u04D9\u043C\u0430\u0442\u0442\u0443\u0493 \u04AF\u0448\u0456\u043D \u043E\u0434\u0430\u043D \u043A\u0435\u0439\u0456\u043D \u049B\u0430\u0436\u044B\u043B\u044B\u049B\u0442\u044B\u04A3 \u0441\u04D9\u0493\u0438\u0441\u0456\u043D \u0436\u0430\u0441\u0430\u04A3\u044B\u0437 (\u043D\u0435\u043C\u0435\u0441\u0435 \u0441\u04D9\u0493\u0438\u0434\u0456 \u0418\u0444\u0430\u0434\u0430 \u0442\u0430\u0443\u0430\u0431\u044B\u043D\u0430\u043D \u043A\u0435\u0439\u0456\u043D\u0433\u0435 \u049B\u0430\u043B\u0434\u044B\u0440\u044B\u04A3\u044B\u0437 \u2014 \u0435\u043A\u0435\u0443\u0456\u043D \u0434\u0435 \u04D9\u0440 \u043C\u0430\u0437\u04BB\u0430\u0431 \u0434\u04B1\u0440\u044B\u0441 \u0434\u0435\u043F \u0441\u0430\u043D\u0430\u0439\u0434\u044B). \u0421\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0438\u0445\u0440\u0430\u043C\u0434\u0430 \u049B\u0430\u043B\u0430\u0441\u044B\u0437.",
    counterLabel: "\u0410\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u0430\u0440"
  },
  tarwiyah: {
    title: "\u0417\u0443\u043B-\u0425\u0438\u0436\u0436\u0430\u043D\u044B\u04A3 8-\u0456 \u2014 \u041C\u0438\u043D\u0430",
    short: "\u0422\u04D9\u0440\u0443\u0438\u044F \u043A\u04AF\u043D\u0456, \u041C\u0438\u043D\u0430\u0434\u0430 \u04E9\u0442\u0435\u0434\u0456",
    detail: "\u0415\u0433\u0435\u0440 \u0438\u0445\u0440\u0430\u043C\u043D\u0430\u043D \u0448\u044B\u049B\u049B\u0430\u043D \u0431\u043E\u043B\u0441\u0430\u04A3\u044B\u0437, \u049B\u0430\u0436\u044B\u043B\u044B\u049B \u04AF\u0448\u0456\u043D \u049B\u0430\u0439\u0442\u0430 \u0438\u0445\u0440\u0430\u043C\u0493\u0430 \u043A\u0456\u0440\u0456\u04A3\u0456\u0437 \u0434\u0435 \u041C\u0438\u043D\u0430\u0493\u0430 \u0431\u0430\u0440\u044B\u04A3\u044B\u0437; \u043E\u043D\u0434\u0430 \u0431\u0435\u0441\u0456\u043D, \u0435\u043A\u0456\u043D\u0434\u0456, \u0430\u049B\u0448\u0430\u043C, \u049B\u04B1\u043F\u0442\u0430\u043D \u0436\u04D9\u043D\u0435 \u0442\u0430\u04A3 \u043D\u0430\u043C\u0430\u0437\u0434\u0430\u0440\u044B\u043D \u043E\u049B\u044B\u04A3\u044B\u0437 \u2014 \u04D9\u0440\u049B\u0430\u0439\u0441\u044B\u0441\u044B \u0435\u043A\u0456 \u0440\u04D9\u043A\u0430\u0442\u049B\u0430 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u044B\u043B\u0430\u0434\u044B, \u0431\u0456\u0440\u0430\u049B \u049B\u043E\u0441\u044B\u043B\u043C\u0430\u0439\u0434\u044B. \u0410\u0440\u0430\u0444\u0430\u0442\u049B\u0430 \u04E9\u0442\u043F\u0435\u0441 \u0431\u04B1\u0440\u044B\u043D \u0442\u04AF\u043D\u0434\u0456 \u041C\u0438\u043D\u0430\u0434\u0430 \u04E9\u0442\u043A\u0456\u0437\u0456\u04A3\u0456\u0437."
  },
  arafah: {
    title: "\u0417\u0443\u043B-\u0425\u0438\u0436\u0436\u0430\u043D\u044B\u04A3 9-\u044B \u2014 \u0410\u0440\u0430\u0444\u0430\u0442",
    short: "\u049A\u0430\u0436\u044B\u043B\u044B\u049B\u0442\u044B\u04A3 \u04E9\u0437\u0456 \u0431\u043E\u043B\u044B\u043F \u0442\u0430\u0431\u044B\u043B\u0430\u0442\u044B\u043D \u0442\u04B1\u0440\u0443",
    detail: "\u041A\u04AF\u043D \u0448\u044B\u049B\u049B\u0430\u043D\u043D\u0430\u043D \u043A\u0435\u0439\u0456\u043D \u0410\u0440\u0430\u0444\u0430\u0442\u049B\u0430 \u0431\u0430\u0440\u044B\u043F, \u0431\u0435\u0441\u0456\u043D\u043D\u0435\u043D \u043A\u04AF\u043D \u0431\u0430\u0442\u049B\u0430\u043D\u0493\u0430 \u0434\u0435\u0439\u0456\u043D \u0441\u043E\u043D\u0434\u0430 \u0442\u04B1\u0440\u044B\u04A3\u044B\u0437; \u0431\u0435\u0441\u0456\u043D \u043C\u0435\u043D \u0435\u043A\u0456\u043D\u0434\u0456\u043D\u0456 \u049B\u043E\u0441\u044B\u043F \u0436\u04D9\u043D\u0435 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u044B\u043F \u043E\u049B\u044B\u04A3\u044B\u0437. \u0410\u0440\u0430\u0444\u0430\u0442\u0442\u044B\u04A3 \u0431\u04D9\u0440\u0456 \u2014 \u0442\u04B1\u0440\u0430\u0442\u044B\u043D \u043E\u0440\u044B\u043D, \u0431\u0456\u0440\u0430\u049B \u0430\u0434\u0430\u043C\u0434\u0430\u0440 \u0420\u0430\u0445\u043C\u0430\u0442 \u0442\u0430\u0443\u044B\u043D\u0434\u0430\u0493\u044B \u0436\u0430\u0440\u0442\u0430\u0441\u0442\u044B\u04A3 \u0436\u0430\u043D\u044B\u043D\u0430 \u0436\u0438\u043D\u0430\u043B\u0430\u0434\u044B. \u041A\u04AF\u043D\u0434\u0456 \u0442\u04D9\u043B\u0431\u0438\u044F\u043C\u0435\u043D, \u0437\u0456\u043A\u0456\u0440\u043C\u0435\u043D, \u049A\u04B1\u0440\u0430\u043D\u043C\u0435\u043D, \u0442\u04D9\u0443\u0431\u0435\u043C\u0435\u043D \u0436\u04D9\u043D\u0435 \u0434\u04B1\u0493\u0430\u043C\u0435\u043D \u0442\u043E\u043B\u0442\u044B\u0440\u044B\u04A3\u044B\u0437 \u2014 \u049B\u0430\u0436\u044B\u043B\u044B\u049B \u043E\u0441\u044B \u043A\u04AF\u043D\u0433\u0435 \u0442\u0456\u0440\u0435\u043B\u0435\u0434\u0456."
  },
  muzdalifah: {
    title: "\u041C\u04B1\u0437\u0434\u04D9\u043B\u0438\u0444\u0430\u0434\u0430\u0493\u044B \u0442\u04AF\u043D",
    short: "\u041A\u04AF\u043D \u0431\u0430\u0442\u049B\u0430\u043D\u043D\u0430\u043D \u043A\u0435\u0439\u0456\u043D \u0448\u044B\u0493\u044B\u043F, \u043D\u0430\u043C\u0430\u0437 \u043E\u049B\u044B\u043F, \u0442\u0430\u0441 \u0436\u0438\u043D\u0430\u04A3\u044B\u0437",
    detail: "\u0410\u0440\u0430\u0444\u0430\u0442\u0442\u0430\u043D \u043A\u04AF\u043D \u0431\u0430\u0442\u049B\u0430\u043D\u043D\u0430\u043D \u043A\u0435\u0439\u0456\u043D \u2014 \u0442\u0430\u04A3 \u0430\u0442\u043F\u0430\u0439 \u0442\u04B1\u0440\u044B\u043F \u2014 \u0448\u044B\u0493\u044B\u043F, \u041C\u04B1\u0437\u0434\u04D9\u043B\u0438\u0444\u0430\u0493\u0430 \u0431\u0430\u0440\u044B\u04A3\u044B\u0437; \u043E\u043D\u0434\u0430 \u0430\u049B\u0448\u0430\u043C \u043C\u0435\u043D \u049B\u04B1\u043F\u0442\u0430\u043D\u0434\u044B \u049B\u043E\u0441\u044B\u043F \u043E\u049B\u044B\u043F, \u0442\u04AF\u043D\u0435\u043F \u0448\u044B\u0493\u044B\u04A3\u044B\u0437. \u0422\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u0443\u0493\u0430 \u0430\u0440\u043D\u0430\u043B\u0493\u0430\u043D \u0442\u0430\u0441\u0442\u0430\u0440\u0434\u044B \u043E\u0441\u044B \u0436\u0435\u0440\u0434\u0435\u043D \u0436\u0438\u043D\u0430\u04A3\u044B\u0437, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0442\u0430\u04A3\u0493\u0430 \u0434\u0435\u0439\u0456\u043D \u043D\u0435 \u0442\u0430\u04A3 \u043A\u0435\u0437\u0456\u043D\u0434\u0435 \u041C\u0438\u043D\u0430\u0493\u0430 \u0431\u0435\u0442 \u0430\u043B\u044B\u04A3\u044B\u0437."
  },
  aqaba: {
    title: "10-\u044B \u2014 \u04AE\u043B\u043A\u0435\u043D \u0434\u0456\u04A3\u0433\u0435\u043A\u043A\u0435 \u0442\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u0443",
    short: "\u0416\u04D9\u043C\u0440\u04D9\u0442 \u04D9\u043B-\u0410\u049B\u0430\u0431\u0430\u0434\u0430 \u0436\u0435\u0442\u0456 \u0442\u0430\u0441",
    detail: "\u041C\u0438\u043D\u0430\u0434\u0430 \u041C\u0435\u043A\u043A\u0435\u0433\u0435 \u0435\u04A3 \u0436\u0430\u049B\u044B\u043D \u04AF\u043B\u043A\u0435\u043D \u0434\u0456\u04A3\u0433\u0435\u043A\u043A\u0435 (\u04D9\u043B-\u0410\u049B\u0430\u0431\u0430) \u0436\u0435\u0442\u0456 \u0442\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u044B\u04A3\u044B\u0437, \u04D9\u0440 \u043B\u0430\u049B\u0442\u044B\u0440\u0493\u0430\u043D\u0434\u0430 \xAB\u0410\u043B\u043B\u0430\u04BB\u0443 \u04D9\u043A\u0431\u0430\u0440\xBB \u0434\u0435\u04A3\u0456\u0437. \u041E\u0441\u044B \u0442\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u0443\u043C\u0435\u043D \u0438\u0445\u0440\u0430\u043C\u043D\u0430\u043D \u0442\u043E\u043B\u044B\u049B \u0448\u044B\u0493\u0443 \u043A\u04AF\u0448\u0456\u043D\u0435 \u0435\u043D\u0435\u0434\u0456.",
    counterLabel: "\u0422\u0430\u0441\u0442\u0430\u0440"
  },
  hady: {
    title: "10-\u044B \u2014 \u049A\u04B1\u0440\u0431\u0430\u043D \u0448\u0430\u043B\u0443 \u043C\u0435\u043D \u0448\u0430\u0448 \u0430\u043B\u0443",
    short: "\u049A\u04B1\u0440\u0431\u0430\u043D \u0448\u0430\u043B\u0443, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0448\u0430\u0448\u0442\u044B \u049B\u044B\u0440\u0443 \u043D\u0435 \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u0443",
    detail: "\u0422\u04D9\u043C\u0430\u0442\u0442\u0443\u0493 \u043F\u0435\u043D \u049A\u0438\u0440\u0430\u043D \u04AF\u0448\u0456\u043D \u043C\u0456\u043D\u0434\u0435\u0442\u0442\u0456 \u049B\u04B1\u0440\u0431\u0430\u043D\u0434\u044B\u049B\u0442\u044B \u0448\u0430\u043B\u044B\u04A3\u044B\u0437 \u2014 \u0431\u04AF\u0433\u0456\u043D\u0434\u0435 \u049B\u0430\u0436\u044B\u043B\u0430\u0440\u0434\u044B\u04A3 \u043A\u04E9\u0431\u0456 \u04E9\u043A\u0456\u043B\u0435\u0442\u0442\u0456 \u04E9\u043A\u0456\u043B \u0442\u0430\u0493\u0430\u0439\u044B\u043D\u0434\u0430\u0439\u0434\u044B, \u0431\u04B1\u043B \u049B\u0430\u0431\u044B\u043B\u0434\u0430\u043D\u0430\u0434\u044B. \u0421\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0431\u0430\u0441\u0442\u044B \u049B\u044B\u0440\u044B\u04A3\u044B\u0437 \u043D\u0435 \u0448\u0430\u0448\u0442\u044B \u049B\u044B\u0441\u049B\u0430\u0440\u0442\u044B\u04A3\u044B\u0437; \u04D9\u0439\u0435\u043B\u0434\u0435\u0440 \u0431\u0456\u0440 \u0441\u0430\u0443\u0441\u0430\u049B \u04B1\u0448\u044B\u043D\u0434\u0430\u0439 \u043A\u0435\u0441\u0435\u0434\u0456. \u0422\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u0443, \u049B\u04B1\u0440\u0431\u0430\u043D\u0434\u044B\u049B \u0436\u04D9\u043D\u0435 \u0448\u0430\u0448 \u0430\u043B\u0443 \u0430\u044F\u049B\u0442\u0430\u043B\u0493\u0430\u043D \u0441\u043E\u04A3, \u0436\u04B1\u0431\u0430\u0439\u044B\u043C\u0435\u043D \u0436\u0430\u049B\u044B\u043D\u0434\u044B\u049B\u0442\u0430\u043D \u0431\u0430\u0441\u049B\u0430 \u0438\u0445\u0440\u0430\u043C \u0442\u044B\u0439\u044B\u043C \u0441\u0430\u043B\u0493\u0430\u043D\u043D\u044B\u04A3 \u0431\u04D9\u0440\u0456 \u0430\u0434\u0430\u043B \u0431\u043E\u043B\u0430\u0434\u044B."
  },
  ifadah: {
    title: "10-\u043D\u0430\u043D 12-\u0433\u0435 \u0434\u0435\u0439\u0456\u043D \u2014 \u0418\u0444\u0430\u0434\u0430 \u0442\u0430\u0443\u0430\u0431\u044B",
    short: "\u049A\u0430\u0436\u044B\u043B\u044B\u049B\u0442\u044B\u04A3 \u0442\u0456\u0440\u0435\u0433\u0456, \u0436\u04D9\u043D\u0435 \u04D9\u043B\u0456 \u049B\u0430\u0440\u044B\u0437 \u0431\u043E\u043B\u0441\u0430 \u0441\u04D9\u0493\u0438",
    detail: "\u0418\u0444\u0430\u0434\u0430 \u0442\u0430\u0443\u0430\u0431\u044B \u04AF\u0448\u0456\u043D \u041C\u0435\u043A\u043A\u0435\u0433\u0435 \u049B\u0430\u0439\u0442\u044B\u043F, \u0436\u0435\u0442\u0456 \u0430\u0439\u043D\u0430\u043B\u044B\u043C \u0436\u0430\u0441\u0430\u04A3\u044B\u0437; \u0435\u0433\u0435\u0440 \u049B\u0430\u0436\u044B\u043B\u044B\u049B \u04AF\u0448\u0456\u043D \u04D9\u043B\u0456 \u0436\u0430\u0441\u0430\u043C\u0430\u0441\u0430\u04A3\u044B\u0437, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0441\u04D9\u0493\u0438 \u0436\u0430\u0441\u0430\u04A3\u044B\u0437. \u0411\u04B1\u043B \u0442\u0430\u0443\u0430\u043F \u2014 \u043D\u0435\u0433\u0456\u0437\u0433\u0456 \u0442\u0456\u0440\u0435\u043A: \u043E\u043D\u0441\u044B\u0437 \u049B\u0430\u0436\u044B\u043B\u044B\u049B \u0430\u044F\u049B\u0442\u0430\u043B\u043C\u0430\u0439\u0434\u044B.",
    counterLabel: "\u0410\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u0430\u0440"
  },
  tashreeq: {
    title: "11-\u0434\u0435\u043D 13-\u043A\u0435 \u0434\u0435\u0439\u0456\u043D \u2014 \u0422\u04D9\u0448\u0440\u0438\u049B \u043A\u04AF\u043D\u0434\u0435\u0440\u0456",
    short: "\u041A\u04AF\u043D \u0441\u0430\u0439\u044B\u043D \u0442\u04AF\u0441\u0442\u0435\u043D \u043A\u0435\u0439\u0456\u043D \u04AF\u0448 \u0434\u0456\u04A3\u0433\u0435\u043A, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u041C\u0438\u043D\u0430",
    detail: "\u041A\u04AF\u043D \u0441\u0430\u0439\u044B\u043D \u0431\u0435\u0441\u0456\u043D\u043D\u0435\u043D \u043A\u0435\u0439\u0456\u043D \u04AF\u0448 \u0434\u0456\u04A3\u0433\u0435\u043A\u043A\u0435 \u0440\u0435\u0442\u0456\u043C\u0435\u043D \u0442\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u044B\u04A3\u044B\u0437 \u2014 \u043A\u0456\u0448\u0456\u0441\u0456\u043D\u0435, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u043E\u0440\u0442\u0430\u04A3\u0493\u044B\u0441\u044B\u043D\u0430, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u04AF\u043B\u043A\u0435\u043D\u0456\u043D\u0435 \u2014 \u04D9\u0440\u049B\u0430\u0439\u0441\u044B\u0441\u044B\u043D\u0430 \u0436\u0435\u0442\u0456 \u0442\u0430\u0441\u0442\u0430\u043D, \u04D9\u0440 \u043B\u0430\u049B\u0442\u044B\u0440\u0493\u0430\u043D\u0434\u0430 \xAB\u0410\u043B\u043B\u0430\u04BB\u0443 \u04D9\u043A\u0431\u0430\u0440\xBB \u0434\u0435\u043F \u0430\u0439\u0442\u044B\u04A3\u044B\u0437. \u0411\u04B1\u043B \u0442\u04AF\u043D\u0434\u0435\u0440\u0434\u0456 \u041C\u0438\u043D\u0430\u0434\u0430 \u04E9\u0442\u043A\u0456\u0437\u0456\u04A3\u0456\u0437. 12-\u0448\u0456 \u043A\u04AF\u043D\u0456 \u0442\u0430\u0441 \u043B\u0430\u049B\u0442\u044B\u0440\u044B\u043F \u043A\u0435\u0442\u043A\u0435\u043D \u043A\u0456\u0441\u0456 \u043A\u0456\u043D\u04D9\u0441\u0456\u0437 \u043A\u0435\u0442\u0435\u0434\u0456; 13-\u0456\u043D\u0435 \u0434\u0435\u0439\u0456\u043D \u049B\u0430\u043B\u0493\u0430\u043D \u043A\u0456\u0441\u0456 \u0434\u0435 \u043A\u0456\u043D\u04D9\u0441\u0456\u0437 \u049B\u0430\u043B\u0430\u0434\u044B.",
    counterLabel: "\u0422\u0430\u0441\u0442\u0430\u0440"
  },
  wada: {
    title: "\u049A\u043E\u0448\u0442\u0430\u0441\u0443 \u0442\u0430\u0443\u0430\u0431\u044B",
    short: "\u041C\u0435\u043A\u043A\u0435\u0434\u0435\u043D \u043A\u0435\u0442\u0435\u0440 \u0430\u043B\u0434\u044B\u043D\u0434\u0430 \u0423\u0430\u0434\u0430\u0493 \u0442\u0430\u0443\u0430\u0431\u044B",
    detail: "\u04AE\u0439\u0433\u0435 \u049B\u0430\u0439\u0442\u043F\u0430\u0441 \u0431\u04B1\u0440\u044B\u043D \u0436\u0435\u0442\u0456 \u0430\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u044B \u049B\u043E\u0448\u0442\u0430\u0441\u0443 \u0442\u0430\u0443\u0430\u0431\u044B \u0440\u0435\u0442\u0456\u043D\u0434\u0435 \u0436\u0430\u0441\u0430\u04A3\u044B\u0437, \u0441\u043E\u043D\u0430\u043D \u0441\u043E\u04A3 \u0435\u043A\u0456 \u0440\u04D9\u043A\u0430\u0442 \u043E\u049B\u044B\u043F, \u049B\u0430\u0439\u0442\u044B\u04A3\u044B\u0437. \u041C\u0435\u043A\u043A\u0435\u0434\u0435\u043D \u043A\u0435\u0442\u0435\u0442\u0456\u043D \u04D9\u0440\u043A\u0456\u043C \u04AF\u0448\u0456\u043D \u0431\u04B1\u043B \u049B\u0430\u0436\u044B\u043B\u044B\u049B\u0442\u044B\u04A3 \u0441\u043E\u04A3\u0493\u044B \u0493\u04B1\u0440\u043F\u044B.",
    counterLabel: "\u0410\u0439\u043D\u0430\u043B\u044B\u043C\u0434\u0430\u0440"
  }
};

// src/content/journeyVi.ts
var JOURNEY_META_VI = {
  umrah: {
    intro: "Cu\u1ED9c h\xE0nh h\u01B0\u01A1ng nh\u1ECF: Ihram, Tawaf, Sa\u2018i, v\xE0 c\u1EA1o ho\u1EB7c t\u1EC9a t\xF3c. N\xF3 c\xF3 th\u1EC3 \u0111\u01B0\u1EE3c th\u1EF1c hi\u1EC7n v\xE0o b\u1EA5t k\u1EF3 th\u1EDDi \u0111i\u1EC3m n\xE0o trong n\u0103m."
  },
  hajj: {
    intro: "Cu\u1ED9c h\xE0nh h\u01B0\u01A1ng l\u1EDBn, di\u1EC5n ra t\u1EEB ng\xE0y 8 \u0111\u1EBFn ng\xE0y 13 c\u1EE7a th\xE1ng Dhul-Hijjah, v\u1EDBi vi\u1EC7c hi\u1EC7n di\u1EC7n t\u1EA1i \u2018Arafah l\xE0 trung t\xE2m."
  }
};
