  "RITES DONE": "\u0645\u0646\u0627\u0633\u06A9 \u0627\u0646\u062C\u0627\u0645\u200C\u0634\u062F\u0647",
  "Ramadan": "\u0631\u0645\u0636\u0627\u0646",
  "Ramadan Planner": "\u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0631\u06CC\u0632 \u0631\u0645\u0636\u0627\u0646",
  "Ramadan begins": "\u0622\u063A\u0627\u0632 \u0631\u0645\u0636\u0627\u0646",
  "Ramadan centers fasting, prayer, Qur\u2019an, charity, repentance, and good character.": "\u0631\u0645\u0636\u0627\u0646 \u0628\u0631 \u0631\u0648\u0632\u0647\u060C \u0646\u0645\u0627\u0632\u060C \u0642\u0631\u0622\u0646\u060C \u0635\u062F\u0642\u0647\u060C \u062A\u0648\u0628\u0647 \u0648 \u062E\u0648\u0634\u200C\u062E\u0648\u06CC\u06CC \u0627\u0633\u062A\u0648\u0627\u0631 \u0627\u0633\u062A.",
  "Ramadan fast": "\u0631\u0648\u0632\u0647 \u0631\u0645\u0636\u0627\u0646",
  "Ramadan is under way \u2014 day {n}": "\u0631\u0645\u0636\u0627\u0646 \u062F\u0631 \u062C\u0631\u06CC\u0627\u0646 \u0627\u0633\u062A \u2014 \u0631\u0648\u0632 {n}",
  "Ramadan night prayer is a voluntary act of worship performed after Isha.": "\u0646\u0645\u0627\u0632\u0650 \u0634\u0628\u0650 \u0631\u0645\u0636\u0627\u0646 \u0639\u0628\u0627\u062F\u062A\u06CC \u0645\u0633\u062A\u062D\u0628 \u0627\u0633\u062A \u06A9\u0647 \u067E\u0633 \u0627\u0632 \u0639\u0634\u0627 \u0628\u0647 \u062C\u0627\u06CC \u0622\u0648\u0631\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F.",
  "Ramadan through your cycle": "\u0631\u0645\u0636\u0627\u0646 \u062F\u0631 \u0637\u0648\u0644 \u0686\u0631\u062E\u0647\u0654 \u0634\u0645\u0627",
  "Ramadan {year}": "\u0631\u0645\u0636\u0627\u0646 {year}",
  "Ramadan, voluntary and missed fasts": "\u0631\u0645\u0636\u0627\u0646\u060C \u0631\u0648\u0632\u0647\u200C\u0647\u0627\u06CC \u0645\u0633\u062A\u062D\u0628\u06CC \u0648 \u0642\u0636\u0627",
  "Random verse": "\u0622\u06CC\u0647 \u062A\u0635\u0627\u062F\u0641\u06CC",
  "Rate this app": "\u0627\u0645\u062A\u06CC\u0627\u0632 \u0628\u0647 \u0627\u06CC\u0646 \u0628\u0631\u0646\u0627\u0645\u0647",
  "Rather than stopping at the end. Stops at An-Nas.": "\u0628\u0647 \u062C\u0627\u06CC \u062A\u0648\u0642\u0641 \u062F\u0631 \u067E\u0627\u06CC\u0627\u0646. \u062F\u0631 \u0633\u0648\u0631\u0647\u0654 \u0646\u0627\u0633 \u0645\u062A\u0648\u0642\u0641 \u0645\u06CC\u200C\u0634\u0648\u062F.",
  "Read": "\u062E\u0648\u0627\u0646\u062F\u0646",
  "Read all": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0647\u0645\u0647",
  "Read and navigate": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0648 \u067E\u06CC\u0645\u0627\u06CC\u0634",
  "Read by Hizb": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0628\u0631 \u067E\u0627\u06CC\u0647 \u062D\u0632\u0628",
  "Read by Juz": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0628\u0631 \u067E\u0627\u06CC\u0647 \u062C\u0632\u0621",
  "Read from this device \u2014 the network is not reachable right now.": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0627\u0632 \u0627\u06CC\u0646 \u062F\u0633\u062A\u06AF\u0627\u0647 \u2014 \u062F\u0631 \u062D\u0627\u0644 \u062D\u0627\u0636\u0631 \u0634\u0628\u06A9\u0647 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0646\u06CC\u0633\u062A.",
  "Read hadith in English": "\u062E\u0648\u0627\u0646\u062F\u0646 \u062D\u062F\u06CC\u062B \u0628\u0647 \u0627\u0646\u06AF\u0644\u06CC\u0633\u06CC",
  "Read it now": "\u0647\u0645\u200C\u0627\u06A9\u0646\u0648\u0646 \u0628\u062E\u0648\u0627\u0646\u06CC\u062F",
  "Read more": "\u0628\u06CC\u0634\u062A\u0631 \u0628\u062E\u0648\u0627\u0646\u06CC\u062F",
  "Read now": "\u0627\u06A9\u0646\u0648\u0646 \u0628\u062E\u0648\u0627\u0646\u06CC\u062F",
  "Read offline": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0622\u0641\u0644\u0627\u06CC\u0646",
  "Read the full reflection": "\u062E\u0648\u0627\u0646\u062F\u0646 \u062A\u0623\u0645\u0644 \u06A9\u0627\u0645\u0644",
  "Read the meaning and reference, recite from memory, then reveal the verified Arabic text.": "\u0645\u0639\u0646\u0627 \u0648 \u0627\u0631\u062C\u0627\u0639 \u0631\u0627 \u0628\u062E\u0648\u0627\u0646\u06CC\u062F\u060C \u0627\u0632 \u062D\u0641\u0638 \u062A\u0644\u0627\u0648\u062A \u06A9\u0646\u06CC\u062F\u060C \u0633\u067E\u0633 \u0645\u062A\u0646\u0650 \u0639\u0631\u0628\u06CC\u0650 \u062A\u0623\u06CC\u06CC\u062F\u0634\u062F\u0647 \u0631\u0627 \u0622\u0634\u06A9\u0627\u0631 \u06A9\u0646\u06CC\u062F.",
  "Read the rules in colour": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0642\u0648\u0627\u0639\u062F \u0628\u0627 \u0631\u0646\u06AF",
  "Read the verse": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0622\u06CC\u0647",
  "Read the verse for": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0622\u06CC\u0647 \u0628\u0631\u0627\u06CC",
  "Read with verified Arabic and translation": "\u0628\u0627 \u0639\u0631\u0628\u06CC \u0648 \u062A\u0631\u062C\u0645\u0647\u0654 \u062A\u0623\u06CC\u06CC\u062F\u0634\u062F\u0647 \u0628\u062E\u0648\u0627\u0646\u06CC\u062F",
  "Read. Listen. Reflect.": "\u0628\u062E\u0648\u0627\u0646\u06CC\u062F. \u06AF\u0648\u0634 \u062F\u0647\u06CC\u062F. \u0628\u06CC\u0646\u062F\u06CC\u0634\u06CC\u062F.",
  "Reader Settings": "\u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u062E\u0648\u0627\u0646\u062F\u0646",
  "Reader settings": "\u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u062D\u0627\u0644\u062A \u062E\u0648\u0627\u0646\u062F\u0646",
  "Reading": "\u062E\u0648\u0627\u0646\u062F\u0646",
  "Reading Plans": "\u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627\u06CC \u062E\u0648\u0627\u0646\u062F\u0646",
  "Reading mode": "\u062D\u0627\u0644\u062A \u062E\u0648\u0627\u0646\u062F\u0646",
  "Reading plans": "\u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627\u06CC \u062E\u0648\u0627\u0646\u062F\u0646",
  "Reading position saved": "\u0645\u0648\u0642\u0639\u06CC\u062A \u062E\u0648\u0627\u0646\u062F\u0646 \u0630\u062E\u06CC\u0631\u0647 \u0634\u062F",
  "Reading preferences": "\u062A\u0631\u062C\u06CC\u062D\u0627\u062A \u062E\u0648\u0627\u0646\u062F\u0646",
  "Reading settings": "\u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u062E\u0648\u0627\u0646\u062F\u0646",
  "Recall before you reveal": "\u067E\u06CC\u0634 \u0627\u0632 \u0622\u0634\u06A9\u0627\u0631 \u06A9\u0631\u062F\u0646\u060C \u0627\u0632 \u062D\u0641\u0638 \u0628\u0627\u0632\u062E\u0648\u0627\u0646\u06CC \u06A9\u0646\u06CC\u062F",
  "Recent": "\u0627\u062E\u06CC\u0631",
