  "What is wrong?": "\u0645\u0634\u06A9\u0644 \u0686\u06CC\u0633\u062A\u061F",
  "What it needs from you": "\u0627\u0632 \u0634\u0645\u0627 \u0686\u0647 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u062F",
  "What stays on your device": "\u0622\u0646\u0686\u0647 \u0631\u0648\u06CC \u062F\u0633\u062A\u06AF\u0627\u0647 \u0634\u0645\u0627 \u0645\u06CC\u200C\u0645\u0627\u0646\u062F",
  "What stays open when the prayer and the fast are lifted": "\u0622\u0646\u0686\u0647 \u0628\u0627 \u0628\u0631\u062F\u0627\u0634\u062A\u0647 \u0634\u062F\u0646 \u0646\u0645\u0627\u0632 \u0648 \u0631\u0648\u0632\u0647 \u0647\u0645\u0686\u0646\u0627\u0646 \u0628\u0627\u0632 \u0645\u06CC\u200C\u0645\u0627\u0646\u062F",
  "What the app is holding": "\u0622\u0646\u0686\u0647 \u0628\u0631\u0646\u0627\u0645\u0647 \u0646\u06AF\u0647 \u0645\u06CC\u200C\u062F\u0627\u0631\u062F",
