  "Calculate": "\u09B9\u09BF\u09B8\u09BE\u09AC \u0995\u09B0\u09C1\u09A8",
  "Calculate and find": "\u09B9\u09BF\u09B8\u09BE\u09AC \u0995\u09B0\u09C1\u09A8 \u0993 \u0996\u09C1\u0981\u099C\u09C1\u09A8",
  "Calculation method": "\u09B9\u09BF\u09B8\u09BE\u09AC \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF",
  "Canadian Dollar": "\u0995\u09BE\u09A8\u09BE\u09A1\u09BF\u09AF\u09BC\u09BE\u09A8 \u09A1\u09B2\u09BE\u09B0",
  "Cancel": "\u09AC\u09BE\u09A4\u09BF\u09B2",
  "Carry on from here next time": "\u09AA\u09B0\u09C7\u09B0 \u09AC\u09BE\u09B0 \u098F\u0996\u09BE\u09A8 \u09A5\u09C7\u0995\u09C7 \u098F\u0997\u09BF\u09AF\u09BC\u09C7 \u09AF\u09BE\u09A8",
  "Carry on to the next Surah": "\u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 \u09B8\u09C2\u09B0\u09BE\u09AF\u09BC \u098F\u0997\u09BF\u09AF\u09BC\u09C7 \u09AF\u09BE\u09A8",
  "Cash at home": "\u09AC\u09BE\u09A1\u09BC\u09BF\u09A4\u09C7 \u09A8\u0997\u09A6",
  "Catalog carried an edition with no id": "\u0995\u09CD\u09AF\u09BE\u099F\u09BE\u09B2\u0997\u09C7 \u0986\u0987\u09A1\u09BF\u09AC\u09BF\u09B9\u09C0\u09A8 \u098F\u0995\u099F\u09BF \u09B8\u0982\u09B8\u09CD\u0995\u09B0\u09A3 \u099B\u09BF\u09B2",
  "Catalog carried no editions": "\u0995\u09CD\u09AF\u09BE\u099F\u09BE\u09B2\u0997\u09C7 \u0995\u09CB\u09A8\u09CB \u09B8\u0982\u09B8\u09CD\u0995\u09B0\u09A3 \u099B\u09BF\u09B2 \u09A8\u09BE",
  "Catalog was not an object": "\u0995\u09CD\u09AF\u09BE\u099F\u09BE\u09B2\u0997 \u098F\u0995\u099F\u09BF \u0985\u09AC\u099C\u09C7\u0995\u09CD\u099F \u099B\u09BF\u09B2 \u09A8\u09BE",
  "Chafing \u2014 the thing nobody warns you about": "\u0998\u09B0\u09CD\u09B7\u09A3\u099C\u09A8\u09BF\u09A4 \u0995\u09CD\u09B7\u09A4 \u2014 \u09AF\u09C7 \u09AC\u09BF\u09B7\u09AF\u09BC\u09C7 \u0995\u09C7\u0989 \u0986\u0997\u09C7\u0987 \u09B8\u09A4\u09B0\u09CD\u0995 \u0995\u09B0\u09C7 \u09A8\u09BE",
  "Change": "\u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8",
  "Change PIN": "\u09AA\u09BF\u09A8 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8",
  "Change it or switch it off in Settings at any time.": "\u09AF\u09C7\u0995\u09CB\u09A8\u09CB \u09B8\u09AE\u09AF\u09BC \u09B8\u09C7\u099F\u09BF\u0982\u09B8 \u09A5\u09C7\u0995\u09C7 \u098F\u099F\u09BF \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8 \u0995\u09B0\u09C1\u09A8 \u09AC\u09BE \u09AC\u09A8\u09CD\u09A7 \u0995\u09B0\u09C1\u09A8\u0964",
  "Change password": "\u09AA\u09BE\u09B8\u0993\u09AF\u09BC\u09BE\u09B0\u09CD\u09A1 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8",
  "Change the PIN": "\u09AA\u09BF\u09A8 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8 \u0995\u09B0\u09C1\u09A8",
  "Change the time": "\u09B8\u09AE\u09AF\u09BC \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8 \u0995\u09B0\u09C1\u09A8",
  "Changes": "\u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8\u09B8\u09AE\u09C2\u09B9",
  "Changing\u2026": "\u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8 \u09B9\u099A\u09CD\u099B\u09C7\u2026",
  "Chapter": "\u0985\u09A7\u09CD\u09AF\u09BE\u09AF\u09BC",
  "Chapters": "\u0985\u09A7\u09CD\u09AF\u09BE\u09AF\u09BC\u09B8\u09AE\u09C2\u09B9",
  "Charity before the Eid prayer": "\u0988\u09A6\u09C7\u09B0 \u09A8\u09BE\u09AE\u09BE\u099C\u09C7\u09B0 \u0986\u0997\u09C7 \u09A6\u09BE\u09A8",
  "Check in battery settings": "\u09AC\u09CD\u09AF\u09BE\u099F\u09BE\u09B0\u09BF \u09B8\u09C7\u099F\u09BF\u0982\u09B8\u09C7 \u09AF\u09BE\u099A\u09BE\u0987 \u0995\u09B0\u09C1\u09A8",
  "Check location": "\u0985\u09AC\u09B8\u09CD\u09A5\u09BE\u09A8 \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u09C1\u09A8",
  "Check the spelling, or add the place by its coordinates below.": "\u09AC\u09BE\u09A8\u09BE\u09A8 \u09AF\u09BE\u099A\u09BE\u0987 \u0995\u09B0\u09C1\u09A8, \u0985\u09A5\u09AC\u09BE \u09A8\u09BF\u099A\u09C7 \u098F\u09B0 \u09B8\u09CD\u09A5\u09BE\u09A8\u09BE\u0982\u0995 \u09A6\u09BF\u09AF\u09BC\u09C7 \u09B8\u09CD\u09A5\u09BE\u09A8\u099F\u09BF \u09AF\u09CB\u0997 \u0995\u09B0\u09C1\u09A8\u0964",
  "Children": "\u09B8\u09A8\u09CD\u09A4\u09BE\u09A8",
  "Chinese": "\u4E2D\u6587",
  "Choose a PIN": "\u098F\u0995\u099F\u09BF \u09AA\u09BF\u09A8 \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A8",
  "Choose a Tafsir": "\u098F\u0995\u099F\u09BF \u09A4\u09BE\u09AB\u09B8\u09BF\u09B0 \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A8",
  "Choose a backup file": "\u098F\u0995\u099F\u09BF \u09AC\u09CD\u09AF\u09BE\u0995\u0986\u09AA \u09AB\u09BE\u0987\u09B2 \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A8",
  "Choose a city": "\u098F\u0995\u099F\u09BF \u09B6\u09B9\u09B0 \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A8",
  "Choose a city, coordinates, or let the phone decide": "\u098F\u0995\u099F\u09BF \u09B6\u09B9\u09B0 \u09AC\u09BE \u09B8\u09CD\u09A5\u09BE\u09A8\u09BE\u0982\u0995 \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A8, \u0985\u09A5\u09AC\u09BE \u09AB\u09CB\u09A8\u0995\u09C7 \u09A0\u09BF\u0995 \u0995\u09B0\u09A4\u09C7 \u09A6\u09BF\u09A8",
