  "Full-Surah reciter": "\u09AA\u09C2\u09B0\u09CD\u09A3 \u09B8\u09C2\u09B0\u09BE\u09B0 \u0995\u09CD\u09AC\u09BE\u09B0\u09C0",
  "Full-Surah reciters": "\u09AA\u09C2\u09B0\u09CD\u09A3 \u09B8\u09C2\u09B0\u09BE\u09B0 \u0995\u09CD\u09AC\u09BE\u09B0\u09C0\u0997\u09A3",
