  "Go back": "\u09AB\u09BF\u09B0\u09C7 \u09AF\u09BE\u09A8",
  "Go to verse": "\u0986\u09AF\u09BC\u09BE\u09A4\u09C7 \u09AF\u09BE\u09A8",
  "Goal": "\u09B2\u0995\u09CD\u09B7\u09CD\u09AF",
  "Gold": "\u09B8\u09CB\u09A8\u09BE",
  "Gold (grams)": "\u09B8\u09CB\u09A8\u09BE (\u0997\u09CD\u09B0\u09BE\u09AE)",
