  "TRACK trackers": "\u099F\u09CD\u09B0\u09CD\u09AF\u09BE\u0995\u09BE\u09B0\u09B8\u09AE\u09C2\u09B9 \u099F\u09CD\u09B0\u09CD\u09AF\u09BE\u0995 \u0995\u09B0\u09C1\u09A8",
  "TRANSLATION": "\u0985\u09A8\u09C1\u09AC\u09BE\u09A6",
