  "Make-up fast": "\u0B95\u0BB3\u0BBE \u0BA8\u0BCB\u0BA9\u0BCD\u0BAA\u0BC1",
  "Make-up ledger": "\u0B95\u0BB3\u0BBE\u0BAA\u0BCD \u0BAA\u0BA4\u0BBF\u0BB5\u0BC7\u0B9F\u0BC1",
