  "Makki": "\u0BAE\u0B95\u0BCD\u0B95\u0BC0",
  "Malaysian Ringgit": "\u0BAE\u0BB2\u0BC7\u0B9A\u0BBF\u0BAF \u0BB0\u0BBF\u0B99\u0BCD\u0B95\u0BBF\u0B9F\u0BCD",
  "Maliki": "\u0BAE\u0BBE\u0BB2\u0BBF\u0B95\u0BC0",
  "Managed low-priority preparation": "\u0BA8\u0BBF\u0BB0\u0BCD\u0BB5\u0B95\u0BBF\u0B95\u0BCD\u0B95\u0BAA\u0BCD\u0BAA\u0B9F\u0BCD\u0B9F \u0B95\u0BC1\u0BB1\u0BC8\u0BA8\u0BCD\u0BA4 \u0BAE\u0BC1\u0BA9\u0BCD\u0BA9\u0BC1\u0BB0\u0BBF\u0BAE\u0BC8\u0BA4\u0BCD \u0BA4\u0BAF\u0BBE\u0BB0\u0BBF\u0BAA\u0BCD\u0BAA\u0BC1",
