  "RECENT SEARCHES": "\u0B85\u0BA3\u0BCD\u0BAE\u0BC8\u0BAF \u0BA4\u0BC7\u0B9F\u0BB2\u0BCD\u0B95\u0BB3\u0BCD",
  "RECITATION": "\u0B93\u0BA4\u0BC1\u0BA4\u0BB2\u0BCD",
  "RECORDED": "\u0BAA\u0BA4\u0BBF\u0BB5\u0BC1 \u0B9A\u0BC6\u0BAF\u0BCD\u0BAF\u0BAA\u0BCD\u0BAA\u0B9F\u0BCD\u0B9F\u0BA4\u0BC1",
  "RECORDED IN": "\u0BAA\u0BA4\u0BBF\u0BB5\u0BC1 \u0B9A\u0BC6\u0BAF\u0BCD\u0BAF\u0BAA\u0BCD\u0BAA\u0B9F\u0BCD\u0B9F \u0B87\u0B9F\u0BAE\u0BCD",
  "REMEMBER": "\u0BA8\u0BBF\u0BA9\u0BC8\u0BB5\u0BBF\u0BB2\u0BCD \u0B95\u0BCA\u0BB3\u0BCD",
  "REMEMBRANCE AND LEARNING": "\u0BA4\u0BBF\u0B95\u0BCD\u0BB0\u0BC1\u0BAE\u0BCD \u0B95\u0BB1\u0BCD\u0BB1\u0BB2\u0BC1\u0BAE\u0BCD",
  "REMIND ME BEFORE PRAYER": "\u0BA4\u0BCA\u0BB4\u0BC1\u0B95\u0BC8\u0B95\u0BCD\u0B95\u0BC1 \u0BAE\u0BC1\u0BA9\u0BCD \u0B8E\u0BA9\u0B95\u0BCD\u0B95\u0BC1 \u0BA8\u0BBF\u0BA9\u0BC8\u0BB5\u0BC2\u0B9F\u0BCD\u0B9F\u0BC1",
  "RESUME YOUR MUSHAF": "\u0B89\u0B99\u0BCD\u0B95\u0BB3\u0BCD \u0BAE\u0BC1\u0BB8\u0BCD\u0BB9\u0B83\u0BAA\u0BC8\u0BA4\u0BCD \u0BA4\u0BCA\u0B9F\u0BB0\u0BB5\u0BC1\u0BAE\u0BCD",
