  "Recall before you reveal": "\u0BB5\u0BC6\u0BB3\u0BBF\u0BAA\u0BCD\u0BAA\u0B9F\u0BC1\u0BA4\u0BCD\u0BA4\u0BC1\u0BB5\u0BA4\u0BB1\u0BCD\u0B95\u0BC1 \u0BAE\u0BC1\u0BA9\u0BCD \u0BA8\u0BBF\u0BA9\u0BC8\u0BB5\u0BC1\u0B95\u0BC2\u0BB0\u0BCD",
  "Recent": "\u0B85\u0BA3\u0BCD\u0BAE\u0BC8\u0BAF",
  "Recent Surahs": "\u0B85\u0BA3\u0BCD\u0BAE\u0BC8\u0BAF \u0BB8\u0BC2\u0BB0\u0BBE\u0B95\u0BCD\u0B95\u0BB3\u0BCD",
  "Recent days": "\u0B85\u0BA3\u0BCD\u0BAE\u0BC8\u0BAF \u0BA8\u0BBE\u0B9F\u0BCD\u0B95\u0BB3\u0BCD",
  "Recent record": "\u0B85\u0BA3\u0BCD\u0BAE\u0BC8\u0BAF \u0BAA\u0BA4\u0BBF\u0BB5\u0BC1",
