  "chapters": "\u0B85\u0BA4\u0BCD\u0BA4\u0BBF\u0BAF\u0BBE\u0BAF\u0B99\u0BCD\u0B95\u0BB3\u0BCD",
  "choose a plan": "\u0B92\u0BB0\u0BC1 \u0BA4\u0BBF\u0B9F\u0BCD\u0B9F\u0BA4\u0BCD\u0BA4\u0BC8\u0BA4\u0BCD \u0BA4\u0BC7\u0BB0\u0BCD\u0BB5\u0BC1 \u0B9A\u0BC6\u0BAF\u0BCD",
  "clockwise from true north": "\u0B89\u0BA3\u0BCD\u0BAE\u0BC8 \u0BB5\u0B9F\u0B95\u0BCD\u0B95\u0BBF\u0BB2\u0BBF\u0BB0\u0BC1\u0BA8\u0BCD\u0BA4\u0BC1 \u0B95\u0B9F\u0BBF\u0B95\u0BBE\u0BB0\u0BA4\u0BCD \u0BA4\u0BBF\u0B9A\u0BC8\u0BAF\u0BBF\u0BB2\u0BCD",
