  "counted": "\u0B8E\u0BA3\u0BCD\u0BA3\u0BAA\u0BCD\u0BAA\u0B9F\u0BCD\u0B9F\u0BA4\u0BC1",
  "counted so far": "\u0B87\u0BA4\u0BC1\u0BB5\u0BB0\u0BC8 \u0B8E\u0BA3\u0BCD\u0BA3\u0BAA\u0BCD\u0BAA\u0B9F\u0BCD\u0B9F\u0BA4\u0BC1",
  "daily hadith": "\u0B85\u0BA9\u0BCD\u0BB1\u0BBE\u0B9F \u0BB9\u0BA4\u0BC0\u0BB8\u0BCD",
