  "Load more hadith": "\u041A\u04E9\u0431\u0456\u0440\u0435\u043A \u0445\u0430\u0434\u0438\u0441 \u0436\u04AF\u043A\u0442\u0435\u0443",
  "Load this verse": "\u041E\u0441\u044B \u0430\u044F\u0442\u0442\u044B \u0436\u04AF\u043A\u0442\u0435\u0443",
