var ENGLISH_MARKERS = /\b(the|of|and|for|with|from|that|this|your|you|it|is|are|on|in|to|a|an|before|after|until|while|been|have|has|not|or|by|as|at)\b/i;
var fallbacks = [];
var check = (label, got, eng) => {
  if (!got) return;
  if (isBs(got)) return;
  if (SAME_IN_BOSNIAN.some((f) => got.includes(f))) return;
  if (/^[\s\d.,:%·+\-—–/()#×°'"“”“]*$/.test(got)) return;
  if (got.split(/\s+/).length <= 3 && !ENGLISH_MARKERS.test(got)) return;
  if (got === eng) {
    fallbacks.push(`${label}: ${JSON.stringify(got)}`);
    return;
  }
  if (ENGLISH_MARKERS.test(got)) fallbacks.push(`${label} (suspect English): ${JSON.stringify(got)}`);
};
